-- Individual review; preserve manually edited classifications, ownership and history.
BEGIN;
SELECT id FROM "Exercise" WHERE id='00000000-0000-4000-8000-000000000110' FOR UPDATE;
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM "Exercise" WHERE id='00000000-0000-4000-8000-000000000110' AND ("ownerUserId" IS NOT NULL OR name <> 'Cadeira Extensora')) THEN
  RAISE EXCEPTION 'Leg extension identity changed; review manually';
 END IF;
 IF EXISTS (SELECT 1 FROM "Exercise" e WHERE e.id='00000000-0000-4000-8000-000000000110' AND e."ownerUserId" IS NULL AND e."anatomyReview" IS NULL AND (
  NOT EXISTS (SELECT 1 FROM "ExerciseMuscle" m WHERE m."exerciseId"=e.id AND m."muscleGroup"='QUADRICEPS' AND m.role='PRIMARY') OR
  EXISTS (SELECT 1 FROM "ExerciseMuscle" m WHERE m."exerciseId"=e.id AND NOT ((m."muscleGroup"='QUADRICEPS' AND m.role='PRIMARY') OR (m."muscleGroup"='HAMSTRINGS' AND m.role='SECONDARY')))
 )) THEN RAISE EXCEPTION 'Leg extension classification changed; review manually'; END IF;
END $$;
INSERT INTO "ExerciseMuscle" (id,"exerciseId","muscleGroup",role,"createdAt") SELECT gen_random_uuid()::text,e.id,'HAMSTRINGS','SECONDARY',CURRENT_TIMESTAMP FROM "Exercise" e WHERE e.id='00000000-0000-4000-8000-000000000110' AND e."ownerUserId" IS NULL AND e."anatomyReview" IS NULL ON CONFLICT ("exerciseId","muscleGroup") DO NOTHING;
UPDATE "Exercise" e SET "anatomyReview"='{"version":"2026-10-30.1","reviewedAt":"2026-10-30T12:00:00.000Z","variant":"Cadeira extensora bilateral sentada, quadril aproximadamente a 90°, joelhos de 90° a 10° de flexão, rolo anterior distal e mãos nas alças.","aliases":["cadeira extensora","extensora","leg extension","seated leg extension","extensão de joelhos na máquina"],"participants":[{"id":"RECTUS_FEMORIS","label":"Reto femoral","muscleGroup":"QUADRICEPS","role":"PRIMARY","aliases":["quadríceps","reto da coxa"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["AKIMA_2023","LARSEN_2025"]},{"id":"VASTUS_LATERALIS","label":"Vasto lateral","muscleGroup":"QUADRICEPS","role":"PRIMARY","aliases":["quadríceps","vasto externo"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["AKIMA_2023","LARSEN_2025"]},{"id":"VASTUS_MEDIALIS","label":"Vasto medial","muscleGroup":"QUADRICEPS","role":"PRIMARY","aliases":["quadríceps","vasto interno"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["AKIMA_2023","LARSEN_2025"]},{"id":"VASTUS_INTERMEDIUS","label":"Vasto intermédio","muscleGroup":"QUADRICEPS","role":"PRIMARY","aliases":["quadríceps","vasto intermediário"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["AKIMA_2023","LARSEN_2025"]},{"id":"BICEPS_FEMORIS","label":"Bíceps femoral — coativação estabilizadora","muscleGroup":"HAMSTRINGS","role":"SECONDARY","aliases":["bíceps femoral","posteriores da coxa","isquiotibiais"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["COACTIVATION_2018"]}],"sources":[{"id":"AKIMA_2023","title":"Akima et al. — Neuromuscular activation of the quadriceps femoris, including the vastus intermedius, during isokinetic knee extensions (2023)","url":"https://doi.org/10.1038/s41598-023-34532-x","limitation":"Treze homens saudáveis, contrações máximas isocinéticas; não mede a ativação individual na máquina ilustrada nem estabelece ranking de hipertrofia."},{"id":"LARSEN_2025","title":"Larsen et al. — The effects of hip flexion angle on quadriceps femoris muscle hypertrophy in the leg extension exercise (2025)","url":"https://pubmed.ncbi.nlm.nih.gov/39699974/","limitation":"Vinte e dois homens destreinados, dez semanas, 40° versus 90° de flexão do quadril. Diferenças no reto femoral não tornam o encosto ilustrado um ótimo universal."},{"id":"COACTIVATION_2018","title":"Co-Activation, Estimated Anterior and Posterior Cruciate Ligament Forces, and Motor Unit Activation Strategies during the Time Course of Fatigue (2018)","url":"https://pubmed.ncbi.nlm.nih.gov/30248892/","limitation":"Quatorze homens, 25 extensões máximas isocinéticas a 120°/s. Coativação do bíceps femoral; sua representação na máquina comum é extrapolação editorial, não alvo equivalente."}],"notes":"Quadríceps primário, sem ênfase regional ou isolamento de um vasto. Bíceps femoral secundário representa coativação antagonista estabilizadora, não sinergia extensora nem volume equivalente. Outros estabilizadores podem participar; neutralidade da cor não significa inatividade. Encosto, amplitude e cadência são escolhas ilustrativas; sem prescrição individual ou medida de EMG. Vasto intermédio profundo pode ficar oculto pela anatomia superficial.","instructions":{"description":"Extensão bilateral dos joelhos na cadeira extensora, com o quadríceps como motor principal.","setup":"Ajuste o encosto e o assento para alinhar os joelhos ao eixo da máquina. Apoie costas e quadril, posicione o rolo na parte anterior das pernas, acima dos tornozelos, e segure as alças laterais.","execution":"Estenda os joelhos suavemente, sem impulso ou travamento brusco. Retorne de forma controlada à flexão confortável, faça uma pausa breve e repita sem levantar o quadril.","tips":"A ilustração percorre aproximadamente 90° a 10° de flexão dos joelhos. Ajuste amplitude e carga à orientação individual e ao equipamento. Os posteriores da coxa aparecem como coestabilizadores, sem esforço equivalente ao quadríceps. Cores ilustrativas, sem medição de EMG."}}'::jsonb,"updatedAt"=CURRENT_TIMESTAMP WHERE e.id='00000000-0000-4000-8000-000000000110' AND e."ownerUserId" IS NULL AND e."anatomyReview" IS NULL;
COMMIT;
